import {SOLO_NAMES,equipmentClass,itemInfo,QUALITY} from './campaign-growth-data.mjs';
import {equipmentAttributeRows} from './equipment-stats.mjs';
import {FACE_CENTERS} from './lobby-art.mjs?v=20261030-duel12';
export const equipmentOwner=(p,id)=>p.owned.find(h=>['weapon','armor'].some(slot=>p.heroes[h].equipment[slot]===id))||null;
export const bagContents=p=>p.bag.filter(i=>i.type!=='equipment'||!equipmentOwner(p,i.id));
export const equipmentKind=i=>i.slot==='weapon'?(i.role==='melee'?'拳套':'法杖'):(i.role==='melee'?'战甲':'法袍');
export function ownerPortrait(hero){const [x,y]=FACE_CENTERS[hero]||FACE_CENTERS.fire;return `<svg class="gear-owner-portrait" viewBox="${x-40} ${y-40} 80 80" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${SOLO_NAMES[hero]}"><image href="assets/lobby/hero-splashes-v1.png" width="1536" height="1024"/></svg>`;}
export function equipmentDetail(system,p,item,hero,token){const owner=equipmentOwner(p,item.id),eligible=p.owned.filter(h=>equipmentClass(h)===item.role),target=eligible.includes(system.gearTarget)?system.gearTarget:eligible.includes(hero)?hero:eligible[0],info=itemInfo(item),rows=equipmentAttributeRows(item,target||hero),level=item.level||0,cost=60+level*45+(item.quality||0)*30;return `${token(item,{owner,hero:target||hero})}<h3 style="color:${info.color}">${info.name}</h3><div class="gear-kind-line">${QUALITY[item.quality||0].name} · ${equipmentKind(item)} <span>强化 ${level} / 10 · ${item.rank||0}品</span></div><dl class="gear-attribute-list">${rows.map(r=>`<dt>${r.label}</dt><dd>${r.value}</dd>`).join('')}</dl>${owner?`<div class="gear-current-owner">${ownerPortrait(owner)}<span>${SOLO_NAMES[owner]}正在装备</span></div>`:''}<div class="item-actions"><label>装备给谁<select id="gear-target" data-gear-target>${eligible.map(h=>`<option value="${h}" ${target===h?'selected':''}>${SOLO_NAMES[h]}</option>`).join('')}</select></label><button data-equip="${item.id}" ${!target||owner===target?'disabled':''}>${!target?'尚无兼容英雄':owner===target?'已装备':owner?'转交并装备':'装备给'+SOLO_NAMES[target]}</button>${owner?`<button data-unequip-id="${item.id}">卸下装备</button>`:''}<button data-level-equipment="${item.id}" ${level>=10?'disabled':''}>${level>=10?'已满强化':'升级装备 · '+cost+'金币'}</button>${!owner?`<button class="subtle-button" data-sell="${item.id}">出售 · ${info.sell}金币</button>`:''}</div>`;}
export function equipmentPicker(system,p,hero,token){const slot=system.gearSlot,list=p.bag.filter(i=>i.type==='equipment'&&i.slot===slot&&i.role===equipmentClass(hero)),selected=list.find(i=>i.id===system.gearItem)||list.find(i=>i.id===p.heroes[hero].equipment[slot])||list[0];return `<div class="gear-picker-heading"><button data-gear-close>‹ 返回角色档案</button>${system.selector(p,hero)}<h3>${SOLO_NAMES[hero]} · ${slot==='weapon'?'武器':'盔甲'}</h3></div><div class="bag-layout"><section><div class="gear-choice-grid">${list.map(item=>token(item,{owner:equipmentOwner(p,item.id),label:true,action:`data-gear-item="${item.id}"`,extra:item.id===selected?.id?'<em class="selected-ring"></em>':''})).join('')||'<p class="gear-empty">还没有可用的装备，挑战秘境收集战利品。</p>'}</div></section><aside class="item-detail">${selected?equipmentDetail(system,p,selected,hero,token):'<h3>等待新的战利品</h3>'}</aside></div>`;}
